/**
 * skillport MCP server — Cloudflare Worker.
 *
 * Read-only, keyless registry of Agent Skills mirrored from public GitHub
 * repositories. Serves the Model Context Protocol on two transports:
 *
 *   POST /mcp        streamable HTTP (JSON-RPC in, JSON out)
 *   GET  /sse        legacy HTTP+SSE stream, replies posted to /messages
 *
 * Skills come from mcp/src/skills.bundle.json, generated by
 * `npm run skills:sync` from the same files the site renders.
 */
import bundle from "./skills.bundle.json";

type SkillFile = { path: string; bytes: number; sha256: string; text: string };
type Skill = {
  name: string;
  slug: string;
  owner: string;
  repo: string;
  repoUrl: string;
  license: string;
  licenseUrl: string;
  sourcePath: string;
  commit: string;
  version: string;
  category: string;
  language: string;
  color: string;
  stars: number;
  description: string;
  long: string;
  fileCount: number;
  bytes: number;
  packageSha256: string;
  skillMd: string;
  files: SkillFile[];
};

const DATA = bundle as unknown as { generated: string; count: number; skills: Skill[] };
const SKILLS = DATA.skills;
const BY_NAME = new Map(SKILLS.map((skill) => [skill.name.toLowerCase(), skill]));
const CATEGORIES = [...new Set(SKILLS.map((skill) => skill.category))].sort();

const SERVER_INFO = { name: "skillport", version: "1.0.0" };
const PROTOCOL_VERSION = "2025-06-18";
const INSTRUCTIONS =
  "skillport is a public, read-only registry of Agent Skills mirrored from open-source repositories. " +
  "Call skills.search to find a capability, skills.get for its manifest, and skills.install to download " +
  "every file of a pinned version. Write the returned files into your skills directory and follow the " +
  "SKILL.md instructions. No authentication is required.";

const CORS: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Accept, Mcp-Session-Id, MCP-Protocol-Version, Authorization",
  "Access-Control-Expose-Headers": "Mcp-Session-Id",
  "Access-Control-Max-Age": "86400",
};

const RATE_LIMIT_WINDOW_MS = 60_000;
const RATE_LIMIT_MAX = 60;
const RATE_LIMITS = new Map<string, { started: number; count: number }>();

function rateLimit(request: Request): Response | undefined {
  const ip = request.headers.get("CF-Connecting-IP") ?? request.headers.get("X-Forwarded-For")?.split(",", 1)[0]?.trim() ?? "unknown";
  const now = Date.now();
  const current = RATE_LIMITS.get(ip);
  if (!current || now - current.started >= RATE_LIMIT_WINDOW_MS) {
    RATE_LIMITS.set(ip, { started: now, count: 1 });
    return;
  }
  current.count += 1;
  if (current.count <= RATE_LIMIT_MAX) return;
  const retryAfter = Math.max(1, Math.ceil((RATE_LIMIT_WINDOW_MS - (now - current.started)) / 1000));
  return new Response(JSON.stringify({ error: { code: "RATE_LIMITED", message: "too many requests" } }), {
    status: 429,
    headers: { "Content-Type": "application/json; charset=utf-8", "Retry-After": String(retryAfter), ...CORS },
  });
}

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store", ...CORS },
  });

const rpcError = (id: unknown, code: number, message: string, data?: unknown) => ({
  jsonrpc: "2.0",
  id: id ?? null,
  error: data === undefined ? { code, message } : { code, message, data },
});

const rpcResult = (id: unknown, result: unknown) => ({ jsonrpc: "2.0", id: id ?? null, result });

const TOOLS = [
  {
    name: "skills.search",
    title: "Search skills",
    description:
      "Search the registry by what the task needs. Matches skill names, descriptions, categories, tags and source paths. Returns ranked manifests plus the exact skills.install call for each result.",
    inputSchema: {
      type: "object",
      properties: {
        query: { type: "string", description: "What you want to do, e.g. 'review a pull request' or 'build a React component'." },
        category: { type: "string", enum: CATEGORIES, description: "Optional category filter." },
        limit: { type: "integer", minimum: 1, maximum: 25, default: 8, description: "Results to return." },
      },
      additionalProperties: false,
    },
  },
  {
    name: "skills.get",
    title: "Get a skill manifest",
    description:
      "Resolve one skill to its pinned manifest: source repository, commit, licence, package hash, every file with size and sha256, and the SKILL.md instructions.",
    inputSchema: {
      type: "object",
      properties: {
        name: { type: "string", description: "Skill name, e.g. 'pdf' or 'anthropics/pdf'." },
        includeInstructions: { type: "boolean", default: true, description: "Include the SKILL.md body. Set false for metadata only." },
      },
      required: ["name"],
      additionalProperties: false,
    },
  },
  {
    name: "skills.install",
    title: "Install a skill",
    description:
      "Download every file of a pinned skill version as UTF-8 text, with sha256 per file and a package hash. Write the files into your skills directory exactly as returned. Pass version to pin; omit it for the current commit.",
    inputSchema: {
      type: "object",
      properties: {
        name: { type: "string", description: "Skill name, e.g. 'tmux' or 'roerohan/tmux'." },
        version: { type: "string", description: "Pinned version (git commit prefix). Omit to install the current registry copy." },
        files: { type: "array", items: { type: "string" }, description: "Optional subset of file paths to return." },
      },
      required: ["name"],
      additionalProperties: false,
    },
  },
] as const;

type ToolResult = { content: { type: "text"; text: string }[]; isError?: boolean };

function toolResult(payload: unknown): ToolResult {
  return { content: [{ type: "text", text: JSON.stringify(payload, null, 2) }] };
}

function toolError(code: string, message: string, extra: Record<string, unknown> = {}): ToolResult {
  return {
    content: [{ type: "text", text: JSON.stringify({ error: { code, message, ...extra } }, null, 2) }],
    isError: true,
  };
}

function resolveSkill(raw: string): Skill | undefined {
  const name = raw.trim().toLowerCase();
  if (BY_NAME.has(name)) return BY_NAME.get(name);
  const short = name.includes("/") ? name.slice(name.lastIndexOf("/") + 1) : name;
  return BY_NAME.get(short);
}

function summary(skill: Skill) {
  return {
    name: skill.name,
    owner: skill.owner,
    version: skill.version,
    category: skill.category,
    description: skill.description,
    fileCount: skill.fileCount,
    bytes: skill.bytes,
    stars: skill.stars,
    license: skill.license,
    source: `${skill.repo}/${skill.sourcePath}`,
    install: { tool: "skills.install", arguments: { name: skill.name, version: skill.version } },
  };
}

const STOP = new Set(["the", "a", "an", "to", "of", "and", "for", "with", "that", "this", "in", "on", "is", "it", "my", "your", "how", "what"]);

function tokens(text: string): string[] {
  return text
    .toLowerCase()
    .split(/[^a-z0-9+#.-]+/)
    .map((token) => token.replace(/^[.-]+|[.-]+$/g, ""))
    .filter((token) => token.length > 1 && !STOP.has(token));
}

function search(args: { query?: string; category?: string; limit?: number }) {
  const query = (args.query ?? "").trim();
  const category = args.category?.trim();
  const limit = Math.min(Math.max(args.limit ?? 8, 1), 25);
  const terms = tokens(query);

  const scored = SKILLS.map((skill) => {
    const name = skill.name.toLowerCase();
    const description = skill.description.toLowerCase();
    const tags = tokens(`${skill.repo} ${skill.sourcePath} ${skill.category}`);
    let score = 0;
    for (const term of terms) {
      if (name === term) score += 40;
      else if (name.includes(term)) score += 14;
      if (description.includes(term)) score += 6;
      if (tags.includes(term)) score += 5;
      if (skill.skillMd.toLowerCase().includes(term)) score += 1;
    }
    return { skill, score };
  });

  const pool = category
    ? scored.filter(({ skill }) => skill.category.toLowerCase() === category.toLowerCase())
    : scored;

  const ranked = (terms.length === 0 ? pool : pool.filter((entry) => entry.score > 0))
    .sort((a, b) => b.score - a.score || b.skill.stars - a.skill.stars)
    .slice(0, limit)
    .map(({ skill }) => summary(skill));

  return {
    query,
    category: category ?? null,
    registry: { skills: SKILLS.length, categories: CATEGORIES, generated: DATA.generated },
    count: ranked.length,
    results: ranked,
    ...(ranked.length === 0
      ? { hint: `Nothing matched. Browse with { "category": "${CATEGORIES[0]}" } or no query at all.` }
      : {}),
  };
}

function detail(skill: Skill, includeInstructions: boolean) {
  return {
    name: skill.name,
    owner: skill.owner,
    version: skill.version,
    commit: skill.commit,
    category: skill.category,
    description: skill.description,
    long: skill.long,
    source: { repo: skill.repo, url: `${skill.repoUrl}/tree/${skill.commit}/${skill.sourcePath}`, licence: skill.license },
    package: { sha256: skill.packageSha256, fileCount: skill.fileCount, bytes: skill.bytes },
    files: skill.files.map(({ path, bytes, sha256 }) => ({ path, bytes, sha256 })),
    ...(includeInstructions ? { instructions: skill.skillMd } : {}),
    install: { tool: "skills.install", arguments: { name: skill.name, version: skill.version } },
  };
}

function install(skill: Skill, version?: string, only?: string[]) {
  if (version && !skill.commit.startsWith(version.trim().toLowerCase()) && version.trim() !== skill.version) {
    return toolError("VERSION_NOT_FOUND", `skill ${skill.name} has no version "${version}".`, {
      available: [skill.version],
    });
  }

  const wanted = only?.length ? new Set(only.map((file) => file.replace(/^\/+/, ""))) : null;
  const selected = wanted ? skill.files.filter((file) => wanted.has(file.path)) : skill.files;
  const missing = wanted ? [...wanted].filter((file) => !skill.files.some((entry) => entry.path === file)) : [];

  if (selected.length === 0) {
    return toolError("FILE_NOT_FOUND", "none of the requested files exist in this skill.", {
      available: skill.files.map((file) => file.path),
    });
  }

  return {
    name: skill.name,
    owner: skill.owner,
    version: skill.version,
    commit: skill.commit,
    license: skill.license,
    source: `${skill.repo}/${skill.sourcePath}`,
    packageSha256: skill.packageSha256,
    writeTo: `skills/${skill.name}/`,
    note: "Write each file's text verbatim to writeTo + path, then follow SKILL.md. Report the version you installed.",
    files: selected.map((file) => ({ path: file.path, bytes: file.bytes, sha256: file.sha256, text: file.text })),
    ...(missing.length ? { skipped: missing } : {}),
  };
}

function callTool(name: string, args: Record<string, unknown>): ToolResult {
  if (name === "skills.search") return toolResult(search(args as never));

  if (name === "skills.get") {
    const skill = resolveSkill(String(args.name ?? ""));
    if (!skill) return toolError("SKILL_NOT_FOUND", `no skill named "${String(args.name ?? "")}".`, { browse: "skills.search" });
    return toolResult(detail(skill, args.includeInstructions !== false));
  }

  if (name === "skills.install") {
    const skill = resolveSkill(String(args.name ?? ""));
    if (!skill) return toolError("SKILL_NOT_FOUND", `no skill named "${String(args.name ?? "")}".`, { browse: "skills.search" });
    const out = install(skill, typeof args.version === "string" ? args.version : undefined, Array.isArray(args.files) ? (args.files as string[]) : undefined);
    if ("isError" in out) return out as ToolResult;
    return toolResult(out);
  }

  return toolError("UNKNOWN_TOOL", `no tool named "${name}".`, { tools: TOOLS.map((tool) => tool.name) });
}

/** Handles one JSON-RPC message; returns null for notifications. */
function handleMessage(message: any): any | null {
  if (!message || typeof message !== "object" || typeof message.method !== "string") {
    return rpcError(message?.id, -32600, "Invalid Request");
  }

  const { id, method, params } = message;
  const isNotification = id === undefined || id === null;

  switch (method) {
    case "initialize":
      return rpcResult(id, {
        protocolVersion:
          typeof params?.protocolVersion === "string" && params.protocolVersion === "2025-03-26"
            ? "2025-03-26"
            : PROTOCOL_VERSION,
        capabilities: { tools: { listChanged: false } },
        serverInfo: SERVER_INFO,
        instructions: INSTRUCTIONS,
      });
    case "ping":
      return rpcResult(id, {});
    case "tools/list":
      return rpcResult(id, { tools: TOOLS });
    case "tools/call": {
      const toolName = String(params?.name ?? "");
      if (!TOOLS.some((tool) => tool.name === toolName)) {
        return rpcError(id, -32602, `Unknown tool: ${toolName}`, { tools: TOOLS.map((tool) => tool.name) });
      }
      return rpcResult(id, callTool(toolName, (params?.arguments ?? {}) as Record<string, unknown>));
    }
    case "resources/list":
      return rpcResult(id, { resources: [] });
    case "resources/templates/list":
      return rpcResult(id, { resourceTemplates: [] });
    case "prompts/list":
      return rpcResult(id, { prompts: [] });
    case "logging/setLevel":
      return isNotification ? null : rpcResult(id, {});
    default:
      if (method.startsWith("notifications/")) return null;
      return rpcError(id, -32601, `Method not found: ${method}`);
  }
}

function handlePayload(payload: any): any | null {
  if (Array.isArray(payload)) {
    const replies = payload.map(handleMessage).filter((reply) => reply !== null);
    return replies.length ? replies : null;
  }
  return handleMessage(payload);
}

async function readJson(request: Request): Promise<any> {
  const text = await request.text();
  if (!text.trim()) throw new Error("empty body");
  return JSON.parse(text);
}

// ---- legacy HTTP+SSE transport -------------------------------------------------

type SseSession = { push: (event: string, data: string) => void; close: () => void };
const SSE_SESSIONS = new Map<string, SseSession>();

function openSse(sessionId: string): Response {
  const encoder = new TextEncoder();
  let heartbeat = 0;

  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      const send = (chunk: string) => {
        try {
          controller.enqueue(encoder.encode(chunk));
        } catch {
          /* stream already closed */
        }
      };
      const push = (event: string, data: string) => send(`event: ${event}\ndata: ${data}\n\n`);
      const close = () => {
        clearInterval(heartbeat);
        SSE_SESSIONS.delete(sessionId);
        try {
          controller.close();
        } catch {
          /* already closed */
        }
      };

      SSE_SESSIONS.set(sessionId, { push, close });
      push("endpoint", `/messages?sessionId=${sessionId}`);
      heartbeat = setInterval(() => send(`: keepalive ${Date.now()}\n\n`), 20000) as unknown as number;
    },
    cancel() {
      clearInterval(heartbeat);
      SSE_SESSIONS.delete(sessionId);
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "text/event-stream; charset=utf-8",
      "Cache-Control": "no-cache, no-transform",
      Connection: "keep-alive",
      "X-Accel-Buffering": "no",
      ...CORS,
    },
  });
}

// ---- Worker entry --------------------------------------------------------------

export default {
  async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url);
    const pathname = url.pathname.replace(/\/+$/, "") || "/";

    if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: CORS });
    if (request.method !== "GET" && request.method !== "POST") {
      return json({ error: { code: "METHOD_NOT_ALLOWED", message: "only GET, POST and OPTIONS are supported" } }, 405);
    }
    const limited = rateLimit(request);
    if (limited) return limited;

    if (pathname === "/" && request.method === "GET") {
      return json({
        name: "skillport",
        description: "Read-only MCP registry of Agent Skills mirrored from public GitHub repositories.",
        protocol: PROTOCOL_VERSION,
        transport: { streamableHttp: "/mcp", sse: "/sse" },
        tools: TOOLS.map((tool) => tool.name),
        skills: SKILLS.length,
        categories: CATEGORIES,
        auth: "none",
        generated: DATA.generated,
      });
    }

    if (pathname === "/health") {
      return json({ ok: true, skills: SKILLS.length, generated: DATA.generated, tools: TOOLS.length });
    }

    if (pathname === "/skills" && request.method === "GET") {
      return json({ count: SKILLS.length, skills: SKILLS.map(summary) });
    }

    if (pathname.startsWith("/skills/") && request.method === "GET") {
      const skill = resolveSkill(decodeURIComponent(pathname.slice(8)));
      if (!skill) return json({ error: { code: "SKILL_NOT_FOUND" } }, 404);
      return json(detail(skill, url.searchParams.get("instructions") !== "false"));
    }

    if (pathname === "/mcp") {
      if (request.method === "GET") {
        return json({ error: { code: "METHOD_NOT_ALLOWED", message: "POST JSON-RPC to /mcp. The legacy SSE stream is at /sse." } }, 405);
      }
      if (request.method !== "POST") return json({ error: { code: "METHOD_NOT_ALLOWED" } }, 405);

      let payload: any;
      try {
        payload = await readJson(request);
      } catch {
        return json(rpcError(null, -32700, "Parse error"), 400);
      }

      const reply = handlePayload(payload);
      if (reply === null) return new Response(null, { status: 202, headers: CORS });

      // Clients that ask for SSE get a single-event stream, which is also valid
      // for streamable HTTP. Everything else gets a plain JSON body.
      const wantsSse =
        (request.headers.get("Accept") ?? "").includes("text/event-stream") &&
        !(request.headers.get("Accept") ?? "").includes("application/json");

      if (wantsSse) {
        return new Response(`event: message\ndata: ${JSON.stringify(reply)}\n\n`, {
          headers: {
            "Content-Type": "text/event-stream; charset=utf-8",
            "Cache-Control": "no-cache, no-transform",
            ...CORS,
          },
        });
      }
      return json(reply);
    }

    if (pathname === "/sse" && request.method === "GET") {
      const sessionId = crypto.randomUUID();
      return openSse(sessionId);
    }

    if (pathname === "/messages") {
      if (request.method !== "POST") return json({ error: { code: "METHOD_NOT_ALLOWED" } }, 405);
      const sessionId = url.searchParams.get("sessionId") ?? "";
      const session = SSE_SESSIONS.get(sessionId);
      if (!session) return json({ error: { code: "SESSION_NOT_FOUND" } }, 404);

      let payload: any;
      try {
        payload = await readJson(request);
      } catch {
        return json(rpcError(null, -32700, "Parse error"), 400);
      }

      const reply = handlePayload(payload);
      if (reply !== null) session.push("message", JSON.stringify(reply));
      return new Response(null, { status: 202, headers: CORS });
    }

    return json({ error: { code: "NOT_FOUND", message: `no route for ${pathname}` } }, 404);
  },
};
